INSERT INTO `customer_reviews` VALUES (1,'Kasun Perera',5,'Excellent phone condition and super fast delivery. Highly recommended!','Approved',3,'2026-11-01 23:27:09','2026-10-29 20:54:52','2026-11-01 23:27:09'),(2,'Imasha Perera',5,'I traded in my old iPhone 12 for an iPhone 14 Pro. They gave me the best valuation in the market without any hassle, and the top-up payment was so transparent. Highly recommended for phone upgrades!','Approved',3,'2026-11-01 23:23:27','2026-11-01 23:22:44','2026-11-01 23:23:27'),(3,'Sahan Gunasekara',4,'Excellent customer care. The Seoul team answered all my questions on WhatsApp about specs and network bands before ordering. 100% genuine original Korean version. Will definitely purchase again','Approved',3,'2026-11-01 23:54:31','2026-11-01 23:30:32','2026-11-01 23:54:31'),(4,'Dilshan Madusanka',3,'Best prices for genuine Korean flagship phones in Sri Lanka. Got my device delivered with official checking warranty. Smooth transaction and very friendly staff!\"','Approved',3,'2026-11-01 23:54:28','2026-11-01 23:53:52','2026-11-01 23:54:28'),(5,'Nimali Fernando',5,'I traded in my old iPhone 12 for an iPhone 14 Pro. They gave me the best valuation in the market without any hassle, and the top-up payment was so transparent. Highly recommended for phone upgrades!','Approved',3,'2026-11-01 23:54:28','2026-11-01 23:54:18','2026-11-01 23:54:28'),(6,'pasindu',4,'test','Approved',3,'2026-11-03 12:51:12','2026-11-03 12:49:42','2026-11-03 12:51:12'),(7,'sachini',5,'recommended','Approved',3,'2026-11-03 13:41:06','2026-11-03 13:25:59','2026-11-03 13:41:06');
/*!40000 ALTER TABLE `customer_reviews` ENABLE KEYS */;
