INSERT INTO `marketplace_terms` VALUES (1,'SELLER','1.0','SK LABA PHONE Marketplace Seller Terms & Conditions','1. The seller confirms lawful ownership of the listed device.\n2. Listed device condition, battery health, and details must be accurately reported.\n3. Upon buyer purchase confirmation, seller agrees to send/bring device to SK LABA PHONE hub for technician verification.\n4. Platform commission (5%) will be deducted from payout upon successful verification and delivery.\n5. If device fails technician verification or is counterfeit/stolen, it will be rejected and seller bears delivery return costs.',1,NULL,'2026-11-10 08:44:11','2026-11-10 08:44:11'),(2,'BUYER','1.0','SK LABA PHONE Marketplace Buyer Terms & Conditions','1. Marketplace devices are customer-to-customer listings verified by SK LABA PHONE technicians prior to release.\n2. Buyer payment is securely held in escrow until technician verification is completed.\n3. If device condition does not match listing specifications during inspection, buyer receives a 100% full refund.\n4. Once inspected and handed over / delivered, buyer acknowledges having inspected device functionality.',1,NULL,'2026-11-10 08:44:11','2026-11-10 08:44:11');
/*!40000 ALTER TABLE `marketplace_terms` ENABLE KEYS */;
UNLOCK TABLES;

